import {analyze} from './recommendations.js';
let uploaded=null,scale=null,mode='scale',points=[],boxes={},root,state,helpers,observer;
const $=selector=>root.querySelector(selector);
export function renderPlanner(container,appState,services){root=container;state=appState;helpers=services;const {esc,icon,rooms}=helpers;const room=state.room;const previous=state.roomPlans[room]||{};
root.innerHTML=`<section class="planner-intro"><div><div class="eyebrow">MEASURE FIRST. MAKE IT YOURS.</div><h2>Find the right fit for your room.</h2><p>Upload a floor plan, set its scale and mark a room. Or enter clear interior dimensions to get furniture and lighting suggestions.</p></div><span class="privacy-pill">Your plan stays in your browser</span></section><div class="room-saved" aria-label="Room purpose">${rooms.filter(r=>r.id!=='all').map(r=>`<button data-room="${r.id}" class="${room===r.id?'active':''}">${r.name}${state.roomPlans[r.id]?' · Planned':''}</button>`).join('')}</div><div class="planner-layout"><section class="plan-card"><div class="step-label">01 / YOUR FLOOR PLAN</div><h3>Upload your floor plan</h3><label class="upload-box" id="dropzone" ${uploaded?'hidden':''}><input class="file-input" id="floor-file" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"><span>${icon('upload')}</span><strong>Drop your floor plan here</strong><p>Drag and drop, or choose a file<br>JPG, PNG, WebP or PDF · Up to 10 MB</p><span class="upload-cta">Choose a floor plan</span></label><p id="upload-error" class="upload-error" role="alert"></p><div id="loaded-plan" ${uploaded?'':'hidden'}><div class="plan-toolbar"><span id="file-name">${uploaded?esc(uploaded.name):''}</span><div><button class="text-button" id="replace-image">Replace</button> <button class="text-button" id="remove-image">Remove</button></div></div><div class="plan-image-wrap"><img id="floor-image" ${uploaded?`src="${uploaded.url}"`:''} alt="Your uploaded floor plan"><canvas id="plan-canvas" tabindex="0" aria-label="Select both ends of a known distance, then mark a room. You can also enter dimensions in the form."></canvas></div><div class="plan-mode-buttons"><button data-plan-mode="scale" class="${mode==='scale'?'active':''}">1. Mark a known distance</button><button data-plan-mode="room" ${scale?'':'disabled'} class="${mode==='room'?'active':''}">2. Mark room corners</button></div><div class="calibration-controls"><div><label for="reference-length">Actual distance in meters</label><input id="reference-length" type="number" min="0.1" max="100" step="0.01" placeholder="e.g. 3.6"></div><button id="apply-scale">Set scale</button></div><p id="plan-status" role="status">${scale?'Scale set. Select Mark room corners, then click two opposite interior corners.':'Mark both ends of a known distance, then enter its length in meters.'}</p></div><p class="plan-help">No plan? Enter dimensions directly. Use measured dimensions if a photo is distorted. Only the first PDF page is used. Uploaded files are not kept after leaving this page.</p></section><form id="room-form" class="room-form"><div class="step-label">02 / ROOM DETAILS</div><h3>${rooms.find(r=>r.id===room).name} details</h3><div class="field"><label for="dimension-unit">Dimension units</label><select id="dimension-unit"><option value="m">Meters (m)</option><option value="cm">Centimeters (cm)</option><option value="ft">Feet (ft)</option></select></div><div class="field field-row"><div><label for="room-width">Clear width</label><input id="room-width" type="number" min="0.01" step="any" placeholder="e.g. 3.0" value="${Number.isFinite(previous.width)?previous.width:''}" required></div><div><label for="room-length">Clear length</label><input id="room-length" type="number" min="0.01" step="any" placeholder="e.g. 3.6" value="${Number.isFinite(previous.length)?previous.length:''}" required></div></div><div class="field"><label for="occupants">Occupants</label><select id="occupants"><option value="1" ${previous.occupants!==2?'selected':''}>1 person</option><option value="2" ${previous.occupants===2?'selected':''}>2 people (sharing a bed)</option></select></div><div class="field"><label for="person-height">Tallest occupant (cm)</label><input id="person-height" type="number" min="100" max="230" value="${Number.isFinite(previous.height)?previous.height:170}" required></div><div class="field"><label for="room-light">Natural daylight</label><select id="room-light"><option value="bright" ${previous.light==='bright'?'selected':''}>Bright daylight</option><option value="dim" ${!previous.light||previous.light==='dim'?'selected':''}>Limited daylight</option><option value="none" ${previous.light==='none'?'selected':''}>No daylight</option></select></div><button class="primary-button" type="submit">Find my fit ↗</button><p id="room-error" class="input-error" role="alert"></p><p class="fine" id="dimension-source" data-source="${previous.source==='plan'?'plan':'manual'}">${previous.source==='plan'?'Saved dimensions came from a calibrated floor plan.':'Estimates assume an empty rectangle. Subtract space occupied by existing furniture.'}</p></form></div><div id="room-results"></div>`;
root.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{location.hash=`customize/${b.dataset.room}`});$('#floor-file').onchange=e=>loadFile(e.target.files?.[0]);const drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');loadFile(e.dataTransfer.files?.[0])};$('#replace-image').onclick=()=>$('#floor-file').click();$('#remove-image').onclick=()=>{if(uploaded)URL.revokeObjectURL(uploaded.url);uploaded=null;scale=null;boxes={};points=[];mode='scale';renderPlanner(root,state,helpers)};
root.querySelectorAll('[data-plan-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.planMode;points=[];updateMode();draw()});$('#apply-scale').onclick=applyScale;$('#room-form').onsubmit=e=>{e.preventDefault();generate()};$('#dimension-unit').onchange=e=>{const old=e.target.dataset.previous||'m',next=e.target.value,factors={m:1,cm:.01,ft:.3048};for(const id of ['#room-width','#room-length']){const input=$(id);if(input.value)input.value=String(Number((Number(input.value)*factors[old]/factors[next]).toFixed(3)))}e.target.dataset.previous=next};for(const id of ['#room-width','#room-length'])$(id).oninput=()=>{$('#dimension-source').textContent='Dimensions updated manually. Generate new suggestions to apply them.';$('#dimension-source').dataset.source='manual'};
$('#plan-canvas').onclick=onPoint;$('#plan-canvas').onkeydown=e=>{if(e.key==='Escape'){points=[];draw();$('#plan-status').textContent='Current points cleared. Select again.'}};$('#floor-image').onload=()=>{draw();if(observer)observer.disconnect();observer=new ResizeObserver(draw);observer.observe($('#floor-image'))};if(uploaded&&$('#floor-image').complete)draw();if(previous.width&&previous.length){try{renderResults(previous)}catch{}}
}
async function loadFile(file){if(!file)return;$('#upload-error').textContent='';if(file.size>10*1024*1024){$('#upload-error').textContent='This file is over 10 MB. Reduce its size and try again.';return}if(!['image/png','image/jpeg','image/webp','application/pdf'].includes(file.type)){$('#upload-error').textContent='Choose a JPG, PNG, WebP image or PDF.';return}let nextUrl;try{if(file.type==='application/pdf'){$('#upload-error').textContent='Reading the first PDF page…';const pdfjs=await import('../vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='../vendor/pdf.worker.mjs';const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false});const pdf=await task.promise;try{const page=await pdf.getPage(1),v=page.getViewport({scale:1});const viewport=page.getViewport({scale:Math.min(2,1600/Math.max(v.width,v.height))});const canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();nextUrl=URL.createObjectURL(blob)}finally{await pdf.destroy()}}else nextUrl=URL.createObjectURL(file);
const img=new Image();img.src=nextUrl;await img.decode();if(img.naturalWidth>16000||img.naturalHeight>16000||img.naturalWidth*img.naturalHeight>40000000)throw Error('oversized');if(uploaded)URL.revokeObjectURL(uploaded.url);uploaded={url:nextUrl,name:file.name,width:img.naturalWidth,height:img.naturalHeight};scale=null;mode='scale';points=[];boxes={};renderPlanner(root,state,helpers);helpers.toast('Floor plan loaded. Start by marking a known distance.');}catch(error){if(nextUrl)URL.revokeObjectURL(nextUrl);$('#upload-error').textContent=error.message==='oversized'?'Image resolution is too high. Reduce it to under 40 megapixels.':'Cannot read this file. Try an unencrypted PDF or a freshly exported image.';}}
function updateMode(){root.querySelectorAll('[data-plan-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.planMode===mode);b.disabled=b.dataset.planMode==='room'&&!scale});$('#plan-status').textContent=mode==='scale'?'Click both ends of a known distance. Press Esc to cancel.':'Click the top-left and bottom-right interior corners, excluding wall thickness.'}
function onPoint(event){if(!uploaded)return;const rect=$('#plan-canvas').getBoundingClientRect();points.push({x:(event.clientX-rect.left)/rect.width,y:(event.clientY-rect.top)/rect.height});if(points.length>2)points=[points[2]];if(mode==='room'&&points.length===2){const w=Math.abs(points[1].x-points[0].x)*uploaded.width/scale,l=Math.abs(points[1].y-points[0].y)*uploaded.height/scale;if(w<1||l<1||w>20||l>20){$('#plan-status').textContent='Measured dimensions are outside 1–20 meters. Check your scale or selection.';points=[];draw();return}boxes[state.room]={x:Math.min(points[0].x,points[1].x),y:Math.min(points[0].y,points[1].y),w:Math.abs(points[1].x-points[0].x),h:Math.abs(points[1].y-points[0].y)};$('#dimension-unit').value='m';$('#dimension-unit').dataset.previous='m';$('#room-width').value=w.toFixed(2);$('#room-length').value=l.toFixed(2);$('#dimension-source').dataset.source='plan';$('#dimension-source').textContent='Dimensions calculated from your scale and room selection.';$('#plan-status').textContent=`Measured approximately ${w.toFixed(2)} × ${l.toFixed(2)} m. Confirm the dimensions, then select Find my fit.`;points=[]}else $('#plan-status').textContent=points.length===1?'First point marked. Select the second point.':mode==='scale'?'Both ends marked. Enter the actual distance in meters and set the scale.':'Room marked.';draw()}
function applyScale(){const real=Number($('#reference-length').value);if(mode!=='scale'||points.length!==2||!Number.isFinite(real)||real<.1||real>100){$('#plan-status').textContent='Select two points and enter a known distance between 0.1 and 100 meters.';return}const px=Math.hypot((points[1].x-points[0].x)*uploaded.width,(points[1].y-points[0].y)*uploaded.height);if(px<uploaded.width*.01){$('#plan-status').textContent='These points are too close. Choose a longer, clearer reference distance.';return}scale=px/real;boxes={};mode='room';points=[];updateMode();draw();helpers.toast('Scale set. Now mark your room.')}
function draw(){const canvas=$('#plan-canvas');if(!canvas||!uploaded)return;canvas.width=uploaded.width;canvas.height=uploaded.height;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,line=Math.max(2,w/300);ctx.lineWidth=line;ctx.strokeStyle='#194f45';ctx.fillStyle='#194f4520';for(const [room,b] of Object.entries(boxes)){ctx.fillRect(b.x*w,b.y*h,b.w*w,b.h*h);ctx.strokeRect(b.x*w,b.y*h,b.w*w,b.h*h);ctx.font=`${Math.max(14,w/40)}px sans-serif`;ctx.fillStyle='#194f45';ctx.fillText(helpers.rooms.find(r=>r.id===room).name,b.x*w+8,b.y*h+Math.max(24,w/30));ctx.fillStyle='#194f4520'}ctx.strokeStyle='#d37539';ctx.fillStyle='#d37539';for(const p of points){ctx.beginPath();ctx.arc(p.x*w,p.y*h,Math.max(4,w/130),0,Math.PI*2);ctx.fill()}if(points.length===2){ctx.beginPath();ctx.moveTo(points[0].x*w,points[0].y*h);ctx.lineTo(points[1].x*w,points[1].y*h);ctx.stroke()}}
function generate(){const factors={m:1,cm:.01,ft:.3048},factor=factors[$('#dimension-unit').value];const plan={width:Number($('#room-width').value)*factor,length:Number($('#room-length').value)*factor,room:state.room,occupants:Number($('#occupants').value),height:Number($('#person-height').value),light:$('#room-light').value,source:$('#dimension-source').dataset.source||'manual'};try{analyze(plan);state.roomPlans[state.room]=plan;helpers.persist();$('#room-error').textContent='';renderResults(plan);helpers.toast('Suggestions updated for your room.');$('#room-results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}catch(error){$('#room-error').textContent=error.message}}
function renderResults(plan){const {area,results,furniture}=analyze(plan),{esc,rooms,products,searchUrl}=helpers;const room=rooms.find(r=>r.id===plan.room);const viewW=plan.width*100,viewH=plan.length*100;const shape=furniture?`<rect x="${30+furniture.x*100}" y="${30+furniture.y*100}" width="${furniture.w*100}" height="${furniture.l*100}" rx="4" fill="#d7e7bb" stroke="#799663" stroke-width="2"/><text x="${30+furniture.w*50}" y="${30+furniture.l*50}" text-anchor="middle" font-size="12" fill="#194f45">${furniture.label}</text>`:'';
$('#room-results').innerHTML=`<section class="recommendation-panel"><div class="eyebrow">YOUR SPACE, YOUR SHORTLIST</div><h2>${room.name} · ${area.toFixed(1)} m² room plan</h2><p>Based on ${plan.width.toFixed(2)} × ${plan.length.toFixed(2)} m, ${plan.occupants} occupant(s), and daylight. ${plan.source==='plan'?'Dimensions come from your calibrated floor plan.':'Dimensions entered manually.'}</p><div class="recommendation-grid">${results.map(r=>{const product=products.find(p=>p.id===r.product);return `<article class="recommendation"><span class="eyebrow">${r.type==='light'?'LIGHTING':r.type==='bed'?'SLEEP WELL':'SPACE ESSENTIALS'}</span><h3>${r.title}</h3><strong class="metric">${r.metric}</strong><p>${r.description}</p>${product?`<a href="${product.url}" target="_blank" rel="noopener noreferrer">View ${product.store} ${product.name} ↗</a>`:''}${r.query?`<details class="recommended-stores"><summary>${product?'Compare other retailers':'Shop these specifications'}</summary>${['Amazon','Target','Walmart','IKEA'].map(store=>`<a href="${searchUrl(store,r.query)}" target="_blank" rel="noopener noreferrer">Search ${store} ↗</a>`).join('')}</details>`:''}</article>`}).join('')}</div><div class="layout-diagram"><svg role="img" aria-label="${esc(room.name)} rectangular room and suggested furniture footprint, excluding doors and windows" viewBox="0 0 ${viewW+60} ${viewH+70}"><rect x="30" y="30" width="${viewW}" height="${viewH}" fill="white" stroke="#194f45" stroke-width="3"/>${shape}<text x="${viewW/2+30}" y="19" text-anchor="middle" font-size="13" fill="#66785d">${plan.width.toFixed(2)} m</text><text transform="translate(15 ${viewH/2+30}) rotate(-90)" text-anchor="middle" font-size="13" fill="#66785d">${plan.length.toFixed(2)} m</text><text x="${viewW/2+30}" y="${viewH+54}" text-anchor="middle" font-size="11" fill="#809272">Furniture footprint only · Not a complete layout</text></svg></div><p class="planner-note">Suggestions use rectangular dimensions and allowance for circulation. Doors, windows, outlets and fixed structures are not automatically detected. Check actual frame dimensions, door swing, delivery access and rental rules before buying. Lighting values are planning estimates, not measured illumination.</p><a class="detail-primary" href="#general/${plan.room}">View ${room.name} full checklist ↗</a></section>`;
}
